"kind": "propose",
"summary": "Adjust liveness probe initialDelaySeconds and timeoutSeconds to accommodate startup time",
"hypotheses": [
    {
        "root_cause_class": "probe_too_strict_for_startup",
        "summary": "Liveness probe fails before app starts, as evidenced by killed_during_startup=true and probe_kills=true",
        "supporting": ["ev-rollout_history", "ev-pod_states", "ev-target_events"],
        "contradicting": [],
        "missing": ["container_logs_tail"],
        "status": "supported"
    },
    {
        "root_cause_class": "probe_timeout_too_short",
        "summary": "Liveness probe timeout (1s) is too short for app's startup latency",
        "supporting": ["ev-rollout_history", "ev-target_events"],
        "contradicting": [],
        "missing": [],
        "status": "supported"
    }
],
"proposal": {
    "capability": "deployment.set-probes",
    "target": {"group": "apps", "kind": "Deployment", "namespace": "finance", "name": "ledger", "uid": "uid-deployment-ledger"},
    "params": {
        "container": "app",
        "liveness": {
            "initialDelaySeconds": 30,
            "timeoutSeconds": 5
        }
    },
    "expected_effect": "Allow app 30s to start before liveness checks, with 5s timeout for responses",
    "rationale": "Pods are killed after 32s of running (killed_during_startup=true), indicating startup takes longer than probe's 10s initial delay and 1s timeout. Increasing initial delay and timeout aligns with observed startup duration and prevents premature kills.",
    "cited_evidence_ids": ["ev-rollout_history", "ev-pod_states", "ev-target_events"],
    "cited_predicates": ["killed_during_startup", "probe_kills"]
}
}
